from scipy.optimize import least_squares
sst=np.sum((sigma-sigma.mean())**2)
models={
 'A': lambda p: p[0]*np.sin(p[1]*np.sqrt(T)) + p[2]*eps*np.exp(-p[3]*eps) + p[4]*eps**2*T**p[5],
 'B': lambda p: p[0]*np.sin(p[1]*np.sqrt(T)) + p[2]*eps**p[3]*np.exp(-p[4]*eps) + p[5]*np.log(eps)*T**p[6],
 'C': lambda p: p[0]*np.sin(p[1]*np.sqrt(T)) + p[2]*eps*np.exp(-p[3]*eps*T) + p[4]*eps**2 + p[5],
 'D': lambda p: p[0]*np.sin(p[1]*np.sqrt(T)) + p[2]*eps*np.exp(-p[3]*eps) + p[4]*eps*T**p[5] + p[6],
 'E': lambda p: p[0]*np.sin(p[1]*np.sqrt(T)) + p[2]*eps*(1-p[3]*eps) + p[4]*eps*np.exp(-p[5]*eps)*T**p[6]+p[7],
}
rng=np.random.default_rng(0)
for name,f in models.items():
    bestr=None
    for trial in range(40):
        p0=rng.uniform(-2,3,size=8)
        try:
            r=least_squares(lambda p: f(p)-sigma, p0)
        except Exception as ex:
            continue
        if bestr is None or r.cost<bestr.cost: bestr=r
    print(name, 2*bestr.cost/sst, np.round(bestr.x,3))

